// === Tab: mySketch ===
// Chase

const AGENT_COUNT = 30;
const AGENT_RADIUS = 25; 
const OUTER_RADIUS = 360;
const PREDATOR_RADIUS = 50; 
const PREDATOR_SPEED = 2.0; 
const FLEE_RADIUS = 200;    
const FLEE_FORCE = 0.8;     
const SEEK_FORCE = 0.1;    
const SEPARATION_FORCE = 0.25; 
const DAMPING = 0.92; 
const BOUNDARY_REBOUND = 1.2;
const MIN_SEP_DIST = AGENT_RADIUS * 2.1;
const MIN_SEP_DIST_SQ = MIN_SEP_DIST * MIN_SEP_DIST;
const PREDATOR_COL_DIST = PREDATOR_RADIUS + AGENT_RADIUS;

const agents = [];
let predator;
let arenaModel;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  perspective(PI / 3, width / height, 0.1, 10000);

  for (let i = 0; i < AGENT_COUNT; i++) {
    const angle = random(TWO_PI);
    const r = random(0, 180); 
    const initialPos = createVector(cos(angle) * r, 0, sin(angle) * r);
    agents.push({
      pos: initialPos.copy(),
      prevPos: initialPos.copy(),
      vel: createVector(0, 0, 0),
      acc: createVector(0, 0, 0),
      dir: i % 2 === 0 ? 1 : -1,
      phaseOffset: random(PI),
      lastAngle: random(TWO_PI)
    });
  }

  predator = {
    pos: createVector(OUTER_RADIUS * 0.8, 0, 0),
    prevPos: createVector(OUTER_RADIUS * 0.8, 0, 0),
    vel: createVector(0, 0, 0),
    dir: 2, 
    phaseOffset: 0,
    lastAngle: PI,
    targetTimer: 0
  };

  arenaModel = buildGeometry(function() {
    noStroke();
    fill(255);
    beginShape(TRIANGLE_FAN);
    vertex(0, 0, 0); 
    const segments = 60;
    for (let i = 0; i <= segments; i++) {
      const angle = (TWO_PI / segments) * i;
      vertex(cos(angle) * (OUTER_RADIUS + 10), 0, sin(angle) * (OUTER_RADIUS + 10));
    }
    endShape();

    push();
    translate(0, -30, 0);
    rotateX(HALF_PI);
    fill(150);
    torus(OUTER_RADIUS, 2);
    pop();

    fill(100);
    const postCount = 24;
    const postHeight = 30;
    for (let i = 0; i < postCount; i++) {
      const angle = (TWO_PI / postCount) * i;
      push();
      translate(cos(angle) * OUTER_RADIUS, -postHeight / 2, sin(angle) * OUTER_RADIUS);
      cylinder(3, postHeight);
      pop();
    }
  });
}

function draw() {
  background(0);
  orbitControl();
  rotateX(-0.5);
  scale(1.33);

  const tCommon = frameCount * 0.15;

  push();
  translate(0, 10, 0);
  model(arenaModel); 
  pop();

  updatePhysics();

  const gl = drawingContext;
  gl.enable(gl.POLYGON_OFFSET_FILL);
  gl.polygonOffset(-1.0, -1.0); 

  noStroke();
  fill(0, 10); 

  drawCircleShadow(predator, PREDATOR_COL_DIST * 2.0);
  for (const a of agents) {
    drawCircleShadow(a, MIN_SEP_DIST); 
  }

  gl.disable(gl.POLYGON_OFFSET_FILL);

  drawRobotRepresentation(predator, tCommon, true);
  for (const a of agents) {
    drawRobotRepresentation(a, tCommon, false);
  }
}

function drawCircleShadow(a, size) {
  push();
  translate(a.pos.x, 10, a.pos.z);
  rotateX(HALF_PI);
  circle(0, 0, size);
  pop();
}

function updatePhysics() {
  predator.prevPos.set(predator.pos);
  predator.targetTimer--;
  if (predator.targetTimer <= 0 || !predator.targetAgent) {
    predator.targetAgent = random(agents);
    predator.targetTimer = 300;
  }
  if (predator.targetAgent) {
    let seek = p5.Vector.sub(predator.targetAgent.pos, predator.pos).normalize().mult(PREDATOR_SPEED);
    predator.vel.lerp(seek, 0.05);
  }
  predator.pos.add(predator.vel);
  if (predator.pos.mag() > OUTER_RADIUS - PREDATOR_RADIUS) predator.pos.normalize().mult(OUTER_RADIUS - PREDATOR_RADIUS);

  for (const a of agents) {
    a.prevPos.set(a.pos);

    const dVecP = p5.Vector.sub(a.pos, predator.pos);
    const distP = dVecP.mag();
    if (distP < PREDATOR_COL_DIST) {
      const overlap = PREDATOR_COL_DIST - distP;
      const pushForce = dVecP.copy().normalize().mult(overlap);
      a.pos.add(pushForce);
      a.vel.mult(0.5);
    }

    const toP = p5.Vector.sub(predator.pos, a.pos).normalize();
    const margin = 20;
    if (distP < FLEE_RADIUS - margin) {
      a.acc.add(toP.copy().mult(-FLEE_FORCE));
    } else if (distP > FLEE_RADIUS + margin) {
      a.acc.add(toP.copy().mult(SEEK_FORCE));
    } else {
      const lerpVal = map(distP, FLEE_RADIUS - margin, FLEE_RADIUS + margin, 0, 1);
      const smoothForce = lerp(-FLEE_FORCE, SEEK_FORCE, lerpVal);
      a.acc.add(toP.copy().mult(smoothForce));
    }

    for (const b of agents) {
      if (a === b) continue;
      const diff = p5.Vector.sub(a.pos, b.pos);
      const dSq = diff.magSq();
      if (dSq < MIN_SEP_DIST_SQ && dSq > 0) {
        const d = Math.sqrt(dSq);
        diff.div(d);
        diff.mult((MIN_SEP_DIST - d) * SEPARATION_FORCE);
        a.acc.add(diff);
      }
    }

    if (a.pos.mag() > OUTER_RADIUS - AGENT_RADIUS) {
      a.acc.sub(a.pos.copy().normalize().mult((a.pos.mag() - (OUTER_RADIUS - AGENT_RADIUS)) * BOUNDARY_REBOUND));
    }

    a.vel.add(a.acc).mult(DAMPING);
    a.pos.add(a.vel);

    if (a.pos.mag() > OUTER_RADIUS - AGENT_RADIUS) a.pos.normalize().mult(OUTER_RADIUS - AGENT_RADIUS);
    a.acc.set(0, 0, 0);
  }
}

function smoothAngle(current, target, step) {
  let diff = target - current;
  while (diff < -PI) diff += TWO_PI;
  while (diff > PI) diff -= TWO_PI;
  return current + diff * step;
}

function drawRobotRepresentation(a, tCommon, isPredator) {
  push();
  translate(a.pos.x, 10, a.pos.z);
  const moveDir = p5.Vector.sub(a.pos, a.prevPos);
  if (moveDir.magSq() > 0.0001) {
    const targetAngle = atan2(moveDir.z, moveDir.x);
    a.lastAngle = smoothAngle(a.lastAngle || 0, targetAngle, 0.1);
  }
  rotateY(-(a.lastAngle || 0) - HALF_PI);
  const scaleVal = isPredator ? 1.0 : 0.5;
  scale(scaleVal);
  const t = (isPredator ? tCommon * 0.5 : tCommon) + a.phaseOffset;
  const sM = constrain(a.vel.mag() * 0.8, 0, 1.5);
  const jump = abs(sin(t)) * 10 * sM;
  translate(0, -60 - jump, 0);
  drawLimb(12, 0, 5, t + PI, "leg", sM, isPredator ? 2 : a.dir);
  drawLimb(-12, 0, 5, t, "leg", sM, isPredator ? 2 : a.dir);
  push();
  rotateX(0.2 * sM);
  push(); translate(0, -25, 10); drawBox(0, 0, 0, 30, 50, 20, isPredator ? 2 : a.dir); pop();
  push(); translate(0, -60, 5); drawBox(0, 0, 0, 22, 22, 22, isPredator ? 2 : a.dir); pop();
  drawLimb(22, -45, 10, t, "arm", sM, isPredator ? 2 : a.dir);
  drawLimb(-22, -45, 10, t + PI, "arm", sM, isPredator ? 2 : a.dir);
  pop();
  pop();
}

function drawLimb(x, y, z, phase, type, sM, colorId) {
  const swing = sin(phase) * 0.7 * sM;
  push();
  translate(x, y, z); 
  rotateX(swing);
  drawBox(0, 15, 0, 10, 30, 10, 0);
  translate(0, 30, 0);
  let bend = (type === "leg") ? map(sin(phase - PI/2), -1, 1, 0, 1.2) : -0.6;
  rotateX(bend * sM);
  drawBox(0, 15, 0, 10, 30, 10, 0);
  pop();
}

function drawBox(x, y, z, w, h, d, type) {
  push(); 
  translate(x, y, z);
  stroke(0);
  if (type === 1) fill(0, 200, 255);
  else if (type === -1) fill(255, 100, 150);
  else if (type === 2) fill(255, 215, 0);
  else fill(200, 100);
  box(w, h, d); 
  pop();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
